<span class="line"><span style="color:#ABB2BF;">                prob </span><span style="color:#56B6C2;">=</span><span style="color:#ABB2BF;"> dd.</span><span style="color:#61AFEF;">get</span><span style="color:#ABB2BF;">(</span><span style="color:#98C379;">&quot;probability&quot;</span><span style="color:#ABB2BF;">, </span><span style="color:#D19A66;">0</span><span style="color:#ABB2BF;">)</span></span>
